#include "support/ws_resume_peer.h"
static xmqttauthticket* maTicket(xmqttclient* C,xmqttauthphase Phase)
{double End=xrtTimer()+10;xmqttauthticket* T=NULL;while(!xmqttClientTakeAuth(C,&T)){testRequire(xrtTimer()<End,"application MQTT auth ticket");xrtSleep(1);}testRequire(xmqttAuthPhase(T)==Phase,"MQTT enhanced-auth phase");return T;}
static void maRespond(xmqttauthticket* T)
{xmqttproperty P[2]={{0}};P[0].Id=XMQTT_PROPERTY_AUTH_METHOD;P[0].Type=XMQTT_PROPERTY_STRING;P[0].Value.Text=XRT_STR_LITERAL("m");P[1].Id=XMQTT_PROPERTY_AUTH_DATA;P[1].Type=XMQTT_PROPERTY_BINARY;P[1].Value.Binary=XRT_BYTES_LITERAL("D");xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_AUTH,&Q);Q.Reason=0x18;Q.Properties=(xmqttpropertylist){P,2};testRequire(xmqttAuthRespond(T,&Q)==XMQTT_ADMISSION_ACCEPTED,"application challenge response");}
static void maConfigure(xnetworker* W,ptr Data)
{(void)W;mrPeer* P=Data;P->Peer.Base.Auth=true;xrtAtomic32Store(&P->Configured,2,XMEMORY_RELEASE);}
static void maCase(bool Deny)
{
    mrState S={0};mrPeer P;mrInit(&P,&S,XMQTT_VERSION_5,1,XNET_PORT_SELECT);testRequire(xrtNetEnginePost(P.Peer.Base.Engine,0,maConfigure,&P),"enable literal auth peer on owner");mqttWsWait(&P.Configured,2,"auth peer configured");xmqttauthconfig Auth;xmqttAuthConfigInit(&Auth);P.Peer.Base.WsConfig.Auth=&Auth;xmqttproperty Method={0};Method.Id=XMQTT_PROPERTY_AUTH_METHOD;Method.Type=XMQTT_PROPERTY_STRING;Method.Value.Text=XRT_STR_LITERAL("m");P.Peer.Base.Connect.Properties=(xmqttpropertylist){&Method,1};xmqttclientconfig K;xmqttClientConfigInit(&K);char Authority[128];xmqttclient* C=mrOpen(&P,1,NULL,false,4,&K,Authority,sizeof(Authority));xfuture* Ready=xmqttClientReady(C);xmqttauthticket* T=maTicket(C,XMQTT_AUTH_CHALLENGE);
    mrIssue(&P,1);testRequire(mrCaptured(C,1).Established&&!xrtFutureDone(Ready),"captured native credential never completes MQTT challenge");xtlsresume* Held=NULL;testRequire(xmqttClientTlsTakeResume(C,&Held),"native credential independently transferable while MQTT is quarantined");maRespond(T);xmqttAuthRelease(T);T=maTicket(C,XMQTT_AUTH_VERIFY_CONNECT);mrIssue(&P,1);testRequire(mrCaptured(C,2).CachedBytes&&!xrtFutureDone(Ready),"local proof remains required after another native ticket");
    testRequire(xmqttAuthComplete(T,!Deny)==XMQTT_ADMISSION_ACCEPTED,"explicit local final proof");if(Deny){testRequire(((const xmqttreadyresult*)mqttWsFuture(Ready))->Status==XMQTT_STATUS_AUTHENTICATION&&xmqttClientWaitFor(C,20)==XWAIT_TIMEOUT,"failed proof retains actual held ticket duty");xmqttAuthRelease(T);}else{xmqttAuthRelease(T);testRequire(((const xmqttreadyresult*)mqttWsFuture(Ready))->Status==XMQTT_STATUS_OK,"accepted MQTT final proof");xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_AUTH,&Q);Q.Reason=0x19;Q.Properties=(xmqttpropertylist){&Method,1};xfuture* F=NULL;testRequire(xmqttClientReauthenticateAsync(C,&Q,10000,&F)==XMQTT_ADMISSION_ACCEPTED,"ordinary reauthentication");T=maTicket(C,XMQTT_AUTH_VERIFY_REAUTH);mrIssue(&P,1);(void)mrCaptured(C,3);mrPublish(C,1);testRequire(xmqttAuthComplete(T,true)==XMQTT_ADMISSION_ACCEPTED,"reauth proof independent of native cache");xmqttAuthRelease(T);testRequire(((const xmqttauthresult*)mqttWsFuture(F))->Status==XMQTT_STATUS_OK,"reauth result");xrtFutureDestroy(F);}
    testRequire(xmqttClientClose(C)&&xmqttClientWaitFor(C,15000)==XWAIT_OK&&xmqttClientDestroy(C),"auth/native duties physically joined");mqttWsConnectStop(&P.Peer);xtlsresumeinfo I;testRequire(Held&&xrtTlsResumeInfo(Held,&I)&&I.Secret.Size,"TLS credential survives proof denial and actual owner joins");xrtTlsResumeRelease(Held);xrtTlsResumeRelease(S.ServerTicket);xrtFutureDestroy(Ready);
}
int main(void){maCase(false);maCase(true);puts("[PASS] WSS native credentials preserve MQTT challenge/final-proof/reauth/held-ticket quarantine");return 0;}
